// Incrementally fill the holes in the polyhedron
unsigned int nb_holes = 0;
for (auto h : CGAL::halfedges(poly)) {
    if (h->is_border()) {
        std::vector<cg3::cgal::Polyhedron::Facet_handle> patch_facets;
        CGAL::Polygon_mesh_processing::triangulate_hole(
            poly,
            h,
            std::back_inserter(patch_facets),
            CGAL::Polygon_mesh_processing::parameters::vertex_point_map(
                CGAL::get(CGAL::vertex_point, poly)
            ).geom_traits(cg3::cgal::internal::Kernel())
        );
        ++nb_holes;
    }
}

